import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import axios from "axios";

export default function Perfil() {
  const { id } = useParams();
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    axios.get(`http://localhost:3001/usuarios/${id}`)
      .then((res) => setUsuario(res.data))
      .catch((err) => console.error("Erro ao carregar perfil:", err));
  }, [id]);

  if (!usuario) return <p>Carregando perfil...</p>;

  return (
    <div className="card p-4">
      <h3>{usuario.nome}</h3>
      <p><strong>Idade:</strong> {usuario.idade}</p>
      <p><strong>Endereço:</strong> {usuario.rua}, {usuario.bairro}, {usuario.estado}</p>
      <p><strong>Biografia:</strong> {usuario.biografia}</p>
      {usuario.imagem && (
        <img
          src={`http://localhost:3001${usuario.imagem}`}
          alt="Foto de perfil"
          style={{ width: "150px", height: "150px", objectFit: "cover", borderRadius: "50%" }}
          className="mb-3"
        />
      )}
      <Link to={`/editar/${usuario.id}`} className="btn btn-warning">Editar Perfil</Link>
    </div>
  );
}
